    return r
QP._active_set=wrap

def build(ncom, slots_per, mode, E, plen, rho, B, demands, seed=0):
    rng=random.Random(seed)
    # long random paths over E edges (edge e goes node e -> node e+1 style is too rigid);
    # just use random edge multisets (incidence only matters)
    base=[]
    for _ in range(slots_per):
        base.append([rng.randrange(E) for _ in range(plen)])
    paths=[]
    for k in range(ncom):
        paths.append([list(p) for p in base])
    var=[(k,p) for k in range(ncom) for p in range(slots_per)]
    caps=[float(rng.choice([1,1,2,5,100])) for _ in range(E)]
    A=np.zeros((E,len(var)))
    for j,(k,p) in enumerate(var):
        for e in paths[k][p]:
            A[e,j]+=1.0/caps[e]
    Q=np.eye(len(var))+rho*(A.T@A)
    q=-rho*(A.T@np.array(B,dtype=float))
    if mode=='admit': q=q-1.0
    m=ncom
    C=np.zeros((m,len(var))); d=np.array([demands]*m,dtype=float)
    for i in range(m):
        for j,(k,p) in enumerate(var):
            if k==i: C[i,j]=1.0
    eq=[mode=='route']*m
    x0=np.zeros(len(var))
    if mode=='route':
        for i in range(m):
            v=d[i]/slots_per
            for j,(k,p) in enumerate(var):
                if k==i: x0[j]=v
    return Q,q,C,d,eq,x0

for plen in (1,3,6,12):
