            Q,q,C,d,eq,x0=build(ncom,slots,mode,64,plen,8,[0.0]*64,1000.0,seed=ncom+plen)
            counts.clear()
            t=time.time(); x,lam,ok=solve_qp(Q,q,C,d,eq,x0); dt=time.time()-t
            g=Q@x+q; nu=g+C.T@lam; bad=[]
            if x.min()<-1e-9: bad.append('neg')
            for i in range(len(q)):
                if x[i]<=0 and nu[i]<-1e-7: bad.append('nu%d=%g'%(i,nu[i])); break
            for k in range(len(d)):
                if eq[k] and abs(C[k]@x-d[k])>1e-6: bad.append('eq%d'%k); break
                if not eq[k] and (C[k]@x>d[k]+1e-6 or lam[k]<-1e-9): bad.append('in%d'%k); break
            print("plen=%2d %-6s ncom=%2d slots=%d n=%3d %.3fs solves=%d ok=%s %s"%(plen,mode,ncom,slots,len(q),dt,len(counts),ok,bad))
